-- Migration 038: 50 more real, local Georgia organizations, all distinct from
-- migrations 008, 036, and 037. Broad category coverage (all 15 causes) spread
-- across ~20 cities: Atlanta, Savannah, Macon, Augusta, Columbus, Athens,
-- Valdosta, Brunswick/Jekyll, Alpharetta, Sandy Springs, Roswell, Norcross,
-- Clarkston, Canton, Cartersville, Cumming, Decatur, Suwanee, Morrow, and more.
-- Each org was researched individually and its website/volunteer page verified.
-- Pure inserts with fixed ids - safe to re-run, existing rows untouched.

insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  -- ART
  ('c7000000-0000-4000-8000-000000000001', null, 'Fernbank Museum of Natural History', 'A natural-history museum in Atlanta with dinosaurs, a nature preserve, and hands-on science, where volunteers greet guests, interpret exhibits, and help with forest restoration.', 'https://fernbankmuseum.org', 'https://www.google.com/s2/favicons?domain=fernbankmuseum.org&sz=128', 'art', array['recurring', 'family friendly'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c7000000-0000-4000-8000-000000000002', null, 'Michael C. Carlos Museum', 'Emory University''s art and antiquities museum in Atlanta, where volunteer docents lead thousands of children and adults through the galleries each year.', 'https://carlos.emory.edu', 'https://www.google.com/s2/favicons?domain=carlos.emory.edu&sz=128', 'art', array['recurring', 'leadership role'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c7000000-0000-4000-8000-000000000003', null, 'The Columbus Museum', 'One of the largest museums in the Southeast, spanning American art and regional history in Columbus, with docent and program-assistant volunteer roles.', 'https://www.columbusmuseum.org', 'https://www.google.com/s2/favicons?domain=www.columbusmuseum.org&sz=128', 'art', array['recurring', 'leadership role'], false, false, 15, 'United States', 'GA', 'Columbus', true, true, 'both', false),
  ('c7000000-0000-4000-8000-000000000004', null, 'Tubman African American Museum', 'A Macon museum dedicated to African American art, history, and culture, with an Ambassador program for adults and students to serve as docents and event help.', 'https://tubmanmuseum.com', 'https://www.google.com/s2/favicons?domain=tubmanmuseum.com&sz=128', 'art', array['recurring', 'leadership role'], false, false, 13, 'United States', 'GA', 'Macon', true, true, 'both', false),
  ('c7000000-0000-4000-8000-000000000005', null, 'Morris Museum of Art', 'An Augusta museum devoted to the art and artists of the American South, where volunteers lead family tours, prep education supplies, and staff visitor services.', 'https://themorris.org', 'https://www.google.com/s2/favicons?domain=themorris.org&sz=128', 'art', array['recurring', 'creative work'], false, false, 16, 'United States', 'GA', 'Augusta', true, true, 'both', false),
  -- MUSIC
  ('c7000000-0000-4000-8000-000000000006', null, 'Savannah Music Festival', 'One of the leading music festivals in the country, held each spring in Savannah, engaging more than 300 volunteers for hospitality, ushering, and education programs.', 'https://www.savannahmusicfestival.org', 'https://www.google.com/s2/favicons?domain=www.savannahmusicfestival.org&sz=128', 'music', array['recurring', 'creative work', 'good for crews'], false, false, 16, 'United States', 'GA', 'Savannah', true, true, 'both', false),
  ('c7000000-0000-4000-8000-000000000007', null, 'Spivey Hall', 'A world-class concert hall at Clayton State University in Morrow, where volunteer ushers greet patrons and help create a great experience while enjoying live music.', 'https://spiveyhall.org', 'https://www.google.com/s2/favicons?domain=spiveyhall.org&sz=128', 'music', array['recurring', 'creative work'], false, false, 16, 'United States', 'GA', 'Morrow', true, true, 'both', false),
