insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('c8000000-0000-4000-8000-000000000001', 'c7000000-0000-4000-8000-000000000001', 'Greet Guests and Interpret Exhibits at Fernbank', 'art', 'Volunteers welcome guests, help interpret exhibits, and support forest restoration across Fernbank Museum and its nature preserve. Adult volunteers commit to 50 hours a year, and there are options for younger volunteers too. It is a great fit if you love science, nature, and working with the public.', array['recurring', 'family friendly'], 16, false, false, true, '3-4 hrs', 'https://fernbankmuseum.org/support/volunteer/', 'https://fernbankmuseum.org/support/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000002', 'c7000000-0000-4000-8000-000000000002', 'Become a Carlos Museum Docent', 'art', 'Volunteers train with the Docent Guild to lead children and adults through the galleries of Emory''s Michael C. Carlos Museum, sharing a love of art and history. It is a wonderful role if you enjoy public speaking and learning about ancient and world cultures. Docents commit to ongoing tours after training.', array['recurring', 'leadership role'], 18, false, false, true, '2-3 hrs / week', 'https://carlos.emory.edu/docent-guild', 'https://carlos.emory.edu/docent-guild', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000003', 'c7000000-0000-4000-8000-000000000003', 'Volunteer at The Columbus Museum', 'art', 'Volunteers serve as docents and program assistants at The Columbus Museum, one of the largest art-and-history museums in the Southeast. Applicants must be at least 15, and volunteers enjoy perks like class discounts and an annual luncheon. It is a great pick if you love art and history in the Columbus area.', array['recurring', 'leadership role'], 15, false, false, true, '2-3 hrs', 'https://www.columbusmuseum.org/get-involved', 'https://www.columbusmuseum.org/get-involved', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('c8000000-0000-4000-8000-000000000004', 'c7000000-0000-4000-8000-000000000004', 'Join the Tubman Ambassador Program', 'art', 'Volunteers serve as Tubman Ambassadors, helping at events and forums or working as docents at the museum of African American art, history, and culture in Macon. There are roles for adults and for students who meet the program''s academic criteria. It is a meaningful fit if you care about representation and local history.', array['recurring', 'leadership role'], 13, false, false, true, '2-3 hrs', 'https://tubmanmuseum.com/support/volunteer/', 'https://tubmanmuseum.com/support/volunteer/', '2026-01-01T00:00:00Z', 'Macon', 'GA'),
  ('c8000000-0000-4000-8000-000000000005', 'c7000000-0000-4000-8000-000000000005', 'Lead Family Tours at the Morris', 'art', 'Volunteers lead weekend family tours and prep supplies for education programs, or serve as visitor-services ambassadors, at the Morris Museum of Art in Augusta. It is a great fit if you enjoy working with children and families and love Southern art. Roles range from single events to a regular schedule.', array['recurring', 'creative work'], 16, false, false, true, '2-3 hrs', 'https://themorris.org/learn/volunteers/', 'https://themorris.org/learn/volunteers/', '2026-01-01T00:00:00Z', 'Augusta', 'GA'),
  ('c8000000-0000-4000-8000-000000000006', 'c7000000-0000-4000-8000-000000000006', 'Usher at the Savannah Music Festival', 'music', 'Volunteers hand out programs, usher patrons, offer artist and patron hospitality, and help at events during the Savannah Music Festival each spring and at year-round programs. It is a fun way to be around great live music while you help. Sign up online for festival shifts.', array['recurring', 'creative work', 'good for crews'], 16, false, false, true, '3-4 hrs', 'https://www.savannahmusicfestival.org/about/volunteer/', 'https://www.savannahmusicfestival.org/about/volunteer/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('c8000000-0000-4000-8000-000000000007', 'c7000000-0000-4000-8000-000000000007', 'Usher Concerts at Spivey Hall', 'music', 'Volunteers greet patrons, scan tickets, hand out programs, and guide guests to their seats at Spivey Hall, a renowned concert hall at Clayton State University in Morrow. Ushers get to enjoy world-class music while they help. It is a great recurring role for music lovers south of Atlanta.', array['recurring', 'creative work'], 16, false, false, true, '3 hrs', 'https://spiveyhall.org/support/volunteer/', 'https://spiveyhall.org/support/volunteer/', '2026-01-01T00:00:00Z', 'Morrow', 'GA'),
  ('c8000000-0000-4000-8000-000000000008', 'c7000000-0000-4000-8000-000000000008', 'Support Young Musicians at Franklin Pond', 'music', 'Volunteers help at rehearsals, community concerts, and the summer program of Franklin Pond Chamber Music, which trains talented young musicians alongside Atlanta Symphony and Atlanta Opera artists. It is a great fit if you love classical music. Reach out through the site to find a role.', array['recurring', 'creative work'], 14, false, false, true, '2-3 hrs', 'https://franklinpond.org/', 'https://franklinpond.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000009', 'c7000000-0000-4000-8000-000000000009', 'Foster or Support Rescue Pets', 'animals', 'Volunteers foster dogs and cats, help at adoption events, or lend skills in social media, photography, and event planning with Angels Among Us, a foster-based rescue in north metro Atlanta. Fostering is the biggest need, and it is a great option if your family can host a pet. Start with the volunteer form on their site.', array['recurring', 'family friendly'], 14, false, false, true, 'Varies', 'https://angelsrescue.org/', 'https://angelsrescue.org/', '2026-01-01T00:00:00Z', 'Alpharetta', 'GA'),
  ('c8000000-0000-4000-8000-000000000010', 'c7000000-0000-4000-8000-000000000010', 'Be a Habitat Ambassador at Noah''s Ark', 'animals', 'Volunteers help care for the animals and maintain habitats at Noah''s Ark Animal Sanctuary, a 250-acre home for rescued domestic, wildlife, and exotic animals in Locust Grove. Expect hands-on, sometimes messy outdoor work. It is a rare chance to help everything from farm animals to big cats.', array['outdoors', 'recurring', 'family friendly'], 16, false, false, true, '3-4 hrs', 'https://noahs-ark.org/help/volunteer/', 'https://noahs-ark.org/help/volunteer/', '2026-01-01T00:00:00Z', 'Locust Grove', 'GA'),
  ('c8000000-0000-4000-8000-000000000011', 'c7000000-0000-4000-8000-000000000011', 'Help Sea Turtles on Jekyll Island', 'animals', 'Volunteers support patient care and educate guests at the Georgia Sea Turtle Center, a rescue and rehab hospital for sea turtles on Jekyll Island. It is a bucket-list role for anyone who loves marine wildlife and the coast. Check the site for current volunteer openings and requirements.', array['outdoors', 'recurring', 'leadership role'], 16, false, false, true, '3-4 hrs', 'https://www.jekyllisland.com/activities/georgia-sea-turtle-center/', 'https://www.jekyllisland.com/activities/georgia-sea-turtle-center/', '2026-01-01T00:00:00Z', 'Jekyll Island', 'GA'),
  ('c8000000-0000-4000-8000-000000000012', 'c7000000-0000-4000-8000-000000000012', 'Care for Animals or Take a Dog Out', 'animals', 'Volunteers help care for shelter animals or take a dog out for a few hours through the Doggy Day Out program at the Athens Area Humane Society. Volunteers 10 and up are welcome, and those 10 to 16 volunteer alongside a parent. It is one of the most family-friendly animal options in the area.', array['recurring', 'family friendly'], 10, false, false, true, '2-3 hrs', 'https://athenshumanesociety.org/get-involved/volunteer/', 'https://athenshumanesociety.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('c8000000-0000-4000-8000-000000000013', 'c7000000-0000-4000-8000-000000000013', 'Foster and Save Shelter Pets', 'animals', 'Volunteers foster pets, help transport animals, and support hands-on care with Best Friends in Atlanta, which partners with area shelters to save lives. There are roles at events and from home, and most on-site roles ask volunteers to be 18. It is a great fit if you want to help end shelter euthanasia.', array['recurring'], 18, false, false, true, 'Varies', 'https://bestfriends.org/atlanta/volunteer', 'https://bestfriends.org/atlanta/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000014', 'c7000000-0000-4000-8000-000000000014', 'Help Rescue Horses', 'animals', 'Volunteers help care for and rehabilitate rescued horses and support fostering and adoption with the Georgia Equine Rescue League. It is hands-on outdoor work for people who love horses, and no prior experience is required to start. Contact the volunteer coordinator through their site.', array['outdoors', 'physical work', 'recurring'], 16, false, false, true, '2-3 hrs', 'https://gerlltd.org/', 'https://gerlltd.org/', '2026-01-01T00:00:00Z', 'Good Hope', 'GA'),
  ('c8000000-0000-4000-8000-000000000015', 'c7000000-0000-4000-8000-000000000015', 'Sort Food in South Georgia', 'food', 'Volunteers sort and pack donated food in the warehouse at Second Harvest of South Georgia in Valdosta, the largest rural food bank in the state. All volunteers register in advance and must be at least 12. It is steady, rewarding work that reaches families across many rural counties.', array['good for crews', 'family friendly'], 12, false, false, true, '2-3 hrs', 'https://feedingsga.org/serve/', 'https://feedingsga.org/serve/', '2026-01-01T00:00:00Z', 'Valdosta', 'GA'),
  ('c8000000-0000-4000-8000-000000000016', 'c7000000-0000-4000-8000-000000000016', 'Pack Boxes for Northeast Georgia', 'food', 'Volunteers pack food boxes, sort donations, and provide support at the Food Bank of Northeast Georgia in Athens, which serves 15 counties. There are daytime and evening shifts, including some on weekday evenings. It is an easy, high-impact shift for individuals and groups.', array['good for crews', 'family friendly'], 12, false, false, true, '1-2 hrs', 'https://foodbanknega.org/volunteer/', 'https://foodbanknega.org/volunteer/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('c8000000-0000-4000-8000-000000000017', 'c7000000-0000-4000-8000-000000000017', 'Prepare and Deliver Meals in Forsyth', 'food', 'Volunteers prepare, pack, and label meals, stock the food pantry, or deliver meals to families in Forsyth and Dawson counties with Meals By Grace. Individuals and families with children are welcome, which makes it a great group activity. Many volunteers gather on Sunday afternoons.', array['good for crews', 'family friendly', 'recurring'], 12, false, false, true, '2-3 hrs', 'https://mealsbygrace.org/', 'https://mealsbygrace.org/', '2026-01-01T00:00:00Z', 'Cumming', 'GA'),
  ('c8000000-0000-4000-8000-000000000018', 'c7000000-0000-4000-8000-000000000018', 'Be a Camp Counselor at Camp Twin Lakes', 'medicine', 'Volunteers serve as camp counselors and helpers for children and adults with serious illnesses, disabilities, and other challenges at Camp Twin Lakes; the biggest need is volunteer counselors. No medical knowledge is required. It is a joyful, high-impact way to spend a camp session.', array['recurring', 'leadership role', 'outdoors'], 16, false, false, true, 'Varies', 'https://camptwinlakes.org/volunteer/', 'https://camptwinlakes.org/volunteer/', '2026-01-01T00:00:00Z', 'Rutledge', 'GA'),
  ('c8000000-0000-4000-8000-000000000019', 'c7000000-0000-4000-8000-000000000019', 'Support Kids with Diabetes at Camp Kudzu', 'medicine', 'Volunteers help run camps and programs for children and teens living with type 1 diabetes through Camp Kudzu, supporting campers so they can thrive. Medical and general volunteer roles are available. It is especially meaningful if you or someone you know lives with T1D.', array['recurring', 'leadership role', 'outdoors'], 16, false, false, true, 'Varies', 'https://www.campkudzu.org/', 'https://www.campkudzu.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000020', 'c7000000-0000-4000-8000-000000000020', 'Visit Hospice Patients', 'medicine', 'Volunteers provide companionship to hospice patients, and special programs pair veterans to visit veterans or help patients care for their pets, through Hospice Atlanta. A training session prepares you and matches you to the right role. It is a gentle, meaningful way to support people and families at a tender time.', array['recurring'], 18, false, false, true, '1-2 hrs / week', 'https://vnhs.org/get-involved/volunteer/', 'https://vnhs.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000021', 'c7000000-0000-4000-8000-000000000021', 'Help at the Frazer Center', 'medicine', 'Volunteers help with grounds and facilities, special events, and skilled projects at the Frazer Center, which serves children and adults with developmental disabilities. Nearly 250 volunteers pitch in each year. It is a good fit if you want to support an inclusive community close to home.', array['recurring', 'good for crews'], 16, false, false, true, '2-3 hrs', 'https://www.frazercenter.org/volunteers', 'https://www.frazercenter.org/volunteers', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000022', 'c7000000-0000-4000-8000-000000000022', 'Bring Joy to Seniors', 'seniors', 'Volunteers visit residents, lead activities, and share their interests and talents across Jewish HomeLife''s senior communities in metro Atlanta. Whether you have a few hours a week or one hour a month, there is a role for you. It is a warm way to brighten an older adult''s day.', array['recurring', 'creative work'], 14, false, false, true, '1-2 hrs', 'https://www.jewishhomelife.org/contact/volunteer/', 'https://www.jewishhomelife.org/contact/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000023', 'c7000000-0000-4000-8000-000000000023', 'Be a Companion at Annandale Village', 'seniors', 'Volunteers join residents (called villagers) in programs and activities at Annandale Village in Suwanee, a lifelong community for adults with developmental disabilities and brain injuries. Companion roles make a real difference in a villager''s day. It is a great fit if you enjoy one-on-one connection.', array['recurring', 'creative work'], 16, false, false, true, '2-3 hrs', 'https://annandale.org/volunteers/', 'https://annandale.org/volunteers/', '2026-01-01T00:00:00Z', 'Suwanee', 'GA'),
  ('c8000000-0000-4000-8000-000000000024', 'c7000000-0000-4000-8000-000000000024', 'Deliver Furniture and Build Home Kits', 'community', 'Volunteers help clients pick out furniture, sort donations, and assemble kitchen and bedding kits, or ride along on deliveries, with the Furniture Bank of Metro Atlanta. It is hands-on work that turns an empty apartment into a real home for a family leaving homelessness. Great for a group project.', array['good for crews', 'physical work'], 16, false, false, true, '2-3 hrs', 'https://furniturebankatlanta.org/get-involved/volunteer/', 'https://furniturebankatlanta.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000025', 'c7000000-0000-4000-8000-000000000025', 'Support Neighbors at Gateway Center', 'community', 'Volunteers serve meals, sort donations, and support programs that help people experiencing homelessness become self-sufficient at Atlanta''s Gateway Center. Individuals and groups attend a monthly orientation, then can serve seven days a week. It is a direct way to help neighbors rebuild.', array['good for crews', 'recurring'], 16, false, false, true, '2-3 hrs', 'https://www.gatewayctr.org/volunteer/', 'https://www.gatewayctr.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000026', 'c7000000-0000-4000-8000-000000000026', 'Stock the Market and Pantry', 'community', 'Volunteers help in the client-choice food markets, food pantry, thrift store, and empowerment center at the Community Assistance Center in Sandy Springs. There are roles for individuals and groups on a flexible schedule. It is a friendly, well-run place to give a few hours near home.', array['recurring', 'good for crews', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://ourcac.org/individual-volunteer-opportunities/', 'https://ourcac.org/individual-volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Sandy Springs', 'GA'),
  ('c8000000-0000-4000-8000-000000000027', 'c7000000-0000-4000-8000-000000000027', 'Find a Project in Coastal Georgia', 'community', 'United Way of the Coastal Empire connects volunteers with vetted service projects across the Savannah region, so you can browse by cause and sign up quickly. It is the easiest way to try different kinds of volunteering on the coast. Great for individuals, families, and groups.', array['good for crews', 'family friendly'], 16, false, false, true, 'Varies', 'https://uwce.org/volunteer-opportunities/', 'https://uwce.org/volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('c8000000-0000-4000-8000-000000000028', 'c7000000-0000-4000-8000-000000000028', 'Pack and Serve Meals', 'community', 'Volunteers help pack and serve meals for food-insecure neighbors with Solidarity Sandy Springs, which supports people across the north metro area. Individuals and groups are both welcome. It is a straightforward, feel-good way to fight local hunger.', array['good for crews', 'recurring', 'family friendly'], 13, false, false, true, '2-3 hrs', 'https://solidaritysandysprings.org/volunteer-1', 'https://solidaritysandysprings.org/volunteer-1', '2026-01-01T00:00:00Z', 'Sandy Springs', 'GA'),
  ('c8000000-0000-4000-8000-000000000029', 'c7000000-0000-4000-8000-000000000029', 'Mentor Kids at the Boys & Girls Club', 'community', 'Volunteers help with after-school programs, sports, homework help, and events at the Frank Callen Boys & Girls Club, which serves more than 1,500 Savannah youth. It is a great fit for a steady, recurring role working with kids. Reach out through the club to find a fit.', array['recurring', 'leadership role', 'family friendly'], 16, false, false, true, '2-3 hrs / week', 'https://www.fcbgc.org/', 'https://www.fcbgc.org/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('c8000000-0000-4000-8000-000000000030', 'c7000000-0000-4000-8000-000000000030', 'Tutor or Mentor at The Drake House', 'community', 'Volunteers tutor and mentor kids, help in the store and offices, or join landscaping and event teams supporting single mothers and their children experiencing homelessness at The Drake House in Roswell. There are roles for many skills and schedules, including youth groups. Fill out the interest form to start.', array['recurring', 'good for crews', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://thedrakehouse.org/individuals/', 'https://thedrakehouse.org/individuals/', '2026-01-01T00:00:00Z', 'Roswell', 'GA'),
  ('c8000000-0000-4000-8000-000000000031', 'c7000000-0000-4000-8000-000000000031', 'Serve at City of Refuge', 'faith', 'Volunteers serve meals, sort donations, tutor, and support programs spanning food, shelter, job training, and healthcare at City of Refuge on Atlanta''s Westside. There are roles for individuals, families, and groups. It is a welcoming, faith-based place to help families move out of crisis.', array['good for crews', 'recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://www.cityofrefugeatl.org/volunteer/', 'https://www.cityofrefugeatl.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000032', 'c7000000-0000-4000-8000-000000000032', 'Build Homes in Savannah', 'faith', 'Volunteers help build and repair affordable homes or work at the ReStore with Coastal Empire Habitat for Humanity in the Savannah area. No experience is needed on build days, and tools and guidance are provided. It is rewarding, team-based work that leaves a lasting result.', array['good for crews', 'physical work', 'outdoors'], 16, false, false, true, 'Full day', 'https://www.habitatsavannah.org/', 'https://www.habitatsavannah.org/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('c8000000-0000-4000-8000-000000000033', 'c7000000-0000-4000-8000-000000000033', 'Build with Macon Habitat', 'faith', 'Volunteers help build and rehab homes or work at the ReStore with Macon Area Habitat for Humanity, serving the Macon and Milledgeville region. Construction volunteers must be 16 and up and work with skilled staff. It is a great way to learn building skills while helping a family.', array['good for crews', 'physical work', 'outdoors'], 16, false, false, true, 'Full day', 'https://www.maconhabitat.org/volunteer', 'https://www.maconhabitat.org/volunteer', '2026-01-01T00:00:00Z', 'Macon', 'GA'),
  ('c8000000-0000-4000-8000-000000000034', 'c7000000-0000-4000-8000-000000000034', 'Tutor Students After School', 'education', 'Volunteers help students with reading and math after school, donate supplies, or translate at parent-teacher conferences (if bilingual) with Corners Outreach in Peachtree Corners. It is a good fit if you want a steady, recurring role helping kids and families. Bilingual volunteers are especially needed.', array['recurring', 'counts for school hours'], 14, false, false, true, '1-2 hrs / week', 'https://cornersoutreach.org/volunteer', 'https://cornersoutreach.org/volunteer', '2026-01-01T00:00:00Z', 'Norcross', 'GA'),
  ('c8000000-0000-4000-8000-000000000035', 'c7000000-0000-4000-8000-000000000035', 'Help Students Reach College', 'education', 'Volunteers support Atlanta Public Schools students on the path to and through college with Achieve Atlanta, from advising to near-peer support. It is a strong pick if you want to help open doors to higher education. Check the site for current volunteer opportunities.', array['recurring', 'leadership role', 'counts for school hours'], 16, false, false, true, '1-2 hrs / week', 'https://achieveatlanta.org/', 'https://achieveatlanta.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000036', 'c7000000-0000-4000-8000-000000000036', 'Mentor a Cool Girl', 'education', 'Volunteers become a Cool Sister mentor, meeting with a girl to offer friendship, encouragement, and a positive role model through Cool Girls, Inc. Because mentoring is an ongoing relationship, plan for a real, sustained commitment. It is a rewarding way to help a girl build confidence and reach her goals.', array['recurring', 'leadership role', 'counts for school hours'], 18, false, false, true, '1-2 hrs / week', 'https://thecoolgirls.org/get-involved/volunteer/', 'https://thecoolgirls.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000037', 'c7000000-0000-4000-8000-000000000037', 'Mentor Teen Journalists at VOX ATL', 'education', 'Adult volunteers 21 and up mentor teens creating journalism, art, and media in VOX ATL''s after-school program, where teens speak and Atlanta listens. A background check is part of getting started. It is a great fit if you love writing, media, or working with young people.', array['recurring', 'creative work', 'leadership role'], 21, false, false, true, '2-3 hrs / week', 'https://voxatl.org/volunteer/', 'https://voxatl.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000038', 'c7000000-0000-4000-8000-000000000038', 'Tutor a Young Reader', 'education', 'Volunteers tutor an elementary student one-on-one using Reading Partners'' evidence-based curriculum in Atlanta-area Title I schools, committing a little over an hour a week. You must be 18 or older, and training is provided. It is one of the most consistent, high-impact literacy roles around.', array['recurring', 'counts for school hours'], 18, false, false, true, '1 hr / week', 'https://readingpartners.org/get-involved/volunteer/', 'https://readingpartners.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000039', 'c7000000-0000-4000-8000-000000000039', 'Coach Baseball or Tennis with L.E.A.D.', 'sports', 'Volunteers coach and mentor young athletes through L.E.A.D. Center for Youth, which uses baseball and tennis to develop Atlanta youth into community leaders. There are seasonal coaching and event roles. It is a great fit if you love the game and want to be a positive role model.', array['recurring', 'leadership role', 'outdoors'], 16, false, false, true, '2-3 hrs / week', 'https://leadcenterforyouth.org/', 'https://leadcenterforyouth.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000040', 'c7000000-0000-4000-8000-000000000040', 'Coach or Tutor Refugee Youth', 'sports', 'Volunteers coach soccer or tutor refugee students through Fugees Family in Clarkston, which combines sports with a whole-school education model. If you love soccer or want to help newcomers succeed in school, there is a role for you. Coaching rewards a regular, recurring commitment.', array['recurring', 'leadership role', 'counts for school hours'], 16, false, false, true, '2-3 hrs / week', 'https://fugeesfamily.org/', 'https://fugeesfamily.org/', '2026-01-01T00:00:00Z', 'Clarkston', 'GA'),
  ('c8000000-0000-4000-8000-000000000041', 'c7000000-0000-4000-8000-000000000041', 'Welcome Troops at the Airport USO', 'veterans', 'Volunteers greet and support service members and military families passing through the USO center at Hartsfield-Jackson Atlanta International Airport. Volunteers complete an application and onboarding, and most roles ask you to be at least 18. It is a meaningful way to thank those who serve, right in the world''s busiest airport.', array['recurring', 'good for crews'], 18, false, false, true, '3-4 hrs / shift', 'https://georgia.uso.org/support/how-to-help', 'https://georgia.uso.org/support/how-to-help', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000042', 'c7000000-0000-4000-8000-000000000042', 'Lay Wreaths to Honor Veterans', 'veterans', 'Volunteers help place remembrance wreaths on the graves of veterans at the Georgia National Cemetery in Canton each December through Wreaths Across America. It is a moving, family-friendly way to honor those who served, and all ages are welcome. Sign up through the cemetery''s page for the annual date.', array['family friendly', 'good for crews', 'outdoors'], 12, false, false, true, '2-3 hrs', 'https://www.wreathsacrossamerica.org/', 'https://www.wreathsacrossamerica.org/', '2026-01-01T00:00:00Z', 'Canton', 'GA'),
  ('c8000000-0000-4000-8000-000000000043', 'c7000000-0000-4000-8000-000000000043', 'Clean Up a West Atlanta Creek', 'environment', 'Volunteers join creek cleanups, water-quality monitoring, and urban forestry service days with the West Atlanta Watershed Alliance at sites like the Outdoor Activity Center and Cascade Springs. It is hands-on outdoor work that a group can do together. Roles range from one-time events to regular monitoring.', array['outdoors', 'physical work', 'good for crews'], 12, false, false, true, '2-3 hrs', 'https://www.wawa-online.org/get-involved', 'https://www.wawa-online.org/get-involved', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000044', 'c7000000-0000-4000-8000-000000000044', 'Paddle or Clean the South River', 'environment', 'Volunteers join paddling trips and cleanup events with the South River Watershed Alliance to restore water quality and biodiversity in the river southeast of Atlanta. It is a fun, active way to protect a local waterway. Register for an event through their site.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '2-4 hrs', 'https://www.southriverga.org/events', 'https://www.southriverga.org/events', '2026-01-01T00:00:00Z', 'Ellenwood', 'GA'),
  ('c8000000-0000-4000-8000-000000000045', 'c7000000-0000-4000-8000-000000000045', 'Protect the Georgia Coast', 'environment', 'Volunteers support education, community engagement, and stewardship events with One Hundred Miles to protect Georgia''s 100-mile coast. It is a strong pick if you care about the coast, wildlife, and clean water. Reach out through their site to find current opportunities.', array['outdoors', 'good for crews'], 14, false, false, true, 'Varies', 'https://onehundredmiles.org/', 'https://onehundredmiles.org/', '2026-01-01T00:00:00Z', 'Brunswick', 'GA'),
  ('c8000000-0000-4000-8000-000000000046', 'c7000000-0000-4000-8000-000000000046', 'Steward a Community Farm', 'gardening', 'Volunteers help maintain the farm and garden sites where immigrant and refugee farmers grow food through Global Growers Network in the Atlanta area. Expect real, hands-on outdoor work. It is a great way to support local farmers and learn about sustainable agriculture.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.globalgrowers.org/volunteer', 'https://www.globalgrowers.org/volunteer', '2026-01-01T00:00:00Z', 'Avondale Estates', 'GA'),
  ('c8000000-0000-4000-8000-000000000047', 'c7000000-0000-4000-8000-000000000047', 'Work a HABESHA Garden Day', 'gardening', 'Volunteers help plant, tend, and harvest at the HABESHA Gardens and urban farm sites, supporting a Pan-African nonprofit that trains youth in organic agriculture. It is hands-on outdoor work with a strong community and leadership focus. Check the events page for workdays.', array['outdoors', 'physical work', 'leadership role'], 14, false, false, true, '2-3 hrs', 'https://habeshainc.org/', 'https://habeshainc.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000048', 'c7000000-0000-4000-8000-000000000048', 'Mentor Tech Learners at Per Scholas', 'tech', 'Volunteers with tech or professional backgrounds run mock interviews and mentoring sessions for adults in Per Scholas Atlanta''s free technology career-training program. It is a strong fit if you work in IT or tech and want to help someone launch a career. Roles are flexible and impactful.', array['recurring', 'leadership role'], 18, false, false, true, '2-3 hrs', 'https://perscholas.org/locations/atlanta/', 'https://perscholas.org/locations/atlanta/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c8000000-0000-4000-8000-000000000049', 'c7000000-0000-4000-8000-000000000049', 'Train for Disaster Relief', 'disaster', 'Volunteers train and credential with Georgia Baptist Disaster Relief to help after disasters with cleanup and recovery, feeding, shower and laundry units, family care, or chaplaincy. An introductory training gets you started, then you can join specialized teams. It is meaningful, hands-on work when communities need it most.', array['physical work', 'good for crews', 'leadership role'], 18, false, false, true, 'Varies', 'https://gabaptist.org/ministries/disaster-relief/', 'https://gabaptist.org/ministries/disaster-relief/', '2026-01-01T00:00:00Z', 'Duluth', 'GA'),
  ('c8000000-0000-4000-8000-000000000050', 'c7000000-0000-4000-8000-000000000050', 'Bag Groceries or Clear Storm Debris', 'disaster', 'Volunteers bag groceries for community outreach events and help clear debris after storms through Convoy of Hope, which runs a regional distribution center in Cartersville. Individuals and groups are welcome, and many tasks need no special skills. It is a flexible way to help neighbors near and far.', array['physical work', 'good for crews', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://convoyofhope.org/get-involved/volunteer/', 'https://convoyofhope.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Cartersville', 'GA')
on conflict (id) do nothing;
